<script setup lang="ts">
import type { Interests } from '../../../../packages/contracts/src/interests';
const props=defineProps<{articleId:string;topic?:string}>();const member=useMember(),message=ref(''),busy=ref(false),undo=ref<Interests|null>(null);const emit=defineEmits<{changed:[]}>();
async function change(action:'hide'|'mute'|'undo'){if(busy.value)return;busy.value=true;try{await member.refresh();if(!member.session.value){message.value='Sign in to save feed exclusions. Your anonymous reading is unchanged.';return;}const current=(await $fetch<{data:Interests}>('/api/v1/me/interests')).data;if(action==='undo'&&undo.value&&current.revision!==undo.value.revision+1){message.value='Your interests changed since this action. Open Your interests to review them; undo will not overwrite newer choices.';return;}const next=action==='undo'&&undo.value?{...undo.value,revision:current.revision}:structuredClone(current);if(action!=='undo'){undo.value=current;if(action==='hide')next.hiddenStories=[...new Set([...next.hiddenStories,props.articleId])];if(action==='mute'&&props.topic)next.rules=[...next.rules.filter(r=>r.target!==props.topic),{target:props.topic,action:'mute'}];}await member.mutate('/api/v1/me/interests','PUT',{revision:next.revision,status:next.status==='legacy'||next.status==='not_started'?'completed':next.status,rules:next.rules,hiddenStories:next.hiddenStories});message.value=action==='undo'?'Previous interests restored. Refresh your edition.':'Saved. This edition stays ordered; refresh For you to apply.';if(action==='undo')undo.value=null;emit('changed');}catch(e){message.value=memberError(e);}finally{busy.value=false;}}
</script>
<template><div class="feed-controls"><button class="control control--quiet" :disabled="busy" @click="change('hide')">Hide story from For you</button><button v-if="topic" class="control control--quiet" :disabled="busy" @click="change('mute')">Mute this subject</button><button v-if="undo" class="control control--quiet" :disabled="busy" @click="change('undo')">Undo</button><p role="status">{{ message }}</p></div></template>
